/* ============================================
   NAV COMPONENT
   Top navigation bar using ButtonGroup
   ============================================ */

.ds-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 1440px;
  height: 78px;
}

/* ============================================
   BRAND / LOGO
   ============================================ */

.ds-nav__brand {
  display: flex;
  align-items: center;
  gap: var(--gap-500); /* 20px */
  flex-shrink: 0;
  text-decoration: none;
  color: var(--color-text-primary);
}

.ds-nav__brand-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.ds-nav__brand-text {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
}

/* ============================================
   RIGHT SECTION
   ============================================ */

.ds-nav__right {
  display: flex;
  align-items: center;
  gap: var(--gap-1000); /* 24px */
  flex-shrink: 0;
  flex-wrap: nowrap;
}

import React from 'react';
import { ButtonGroup, type ButtonGroupProps } from '../ButtonGroup/ButtonGroup';
import './Nav.css';

export interface NavProps {
  /** Brand/logo text */
  brandText?: string;
  /** Brand icon element (img, svg, etc.) */
  brandIcon?: React.ReactNode;
  /** Navigation buttons config — passed directly to ButtonGroup */
  buttons: ButtonGroupProps['buttons'];
  /** Additional elements rendered after the button group (e.g. ToggleSwitch) */
  trailing?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Nav component from Figma design system
 * Renders a horizontal navigation bar using ButtonGroup
 */
export const Nav = ({
  brandText,
  brandIcon,
  buttons,
  trailing,
  className = '',
}: NavProps) => {
  const baseClass = 'ds-nav';

  return (
    <nav className={`${baseClass} ${className}`}>
      {(brandText || brandIcon) && (
        <div className={`${baseClass}__brand`}>
          {brandIcon && (
            <span className={`${baseClass}__brand-icon`}>{brandIcon}</span>
          )}
          {brandText && (
            <span className={`${baseClass}__brand-text`}>{brandText}</span>
          )}
        </div>
      )}
      <div className={`${baseClass}__right`}>
        <ButtonGroup orientation="horizontal" buttons={buttons} />
        {trailing}
      </div>
    </nav>
  );
};
